#include <cuda_runtime.h>
#include <algorithm>
#include <chrono>
#include <cstring>
#include <memory>
#include <string>
#include <vector>
#include "study_native_kernel.cuh"
#include "study_fixture.h"
static const int NC=5,HT=512,MW=16,MO=121,CAP=64;
static void ck(cudaError_t e){if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(2);}}
__global__ void capture_hash(const loc_ht*table,unsigned*out,int total){int i=blockIdx.x*blockDim.x+threadIdx.x;if(i<total)out[i]=table[i].key.length==int(EMPTY)?0:MurmurHashAligned2(table[i].key,HT);}
struct Buffers{unsigned *cid,*ctg_off,*read_off,*read_count,*prefix,*terms,*lens,*hashes;char *contigs,*reads,*quals,*longest,*temp;double*depth;loc_ht*table;loc_ht_bool*visited;};
template<class T>static T*device_copy(const std::vector<T>&x){T*p;ck(cudaMalloc(&p,x.size()*sizeof(T)));ck(cudaMemcpy(p,x.data(),x.size()*sizeof(T),cudaMemcpyHostToDevice));return p;}
static void reset(Buffers&b){ck(cudaMemset(b.table,0,NC*HT*sizeof(loc_ht)));ck(cudaMemset(b.visited,0,NC*MW*sizeof(loc_ht_bool)));ck(cudaMemset(b.longest,0,NC*MW));ck(cudaMemset(b.temp,0,NC*(MW+MO)));ck(cudaMemset(b.lens,0,NC*4));ck(cudaMemset(b.terms,0,12));}
static double run(Buffers&b){reset(b);ck(cudaDeviceSynchronize());auto start=std::chrono::steady_clock::now();iterative_walks_kernel<<<1,512>>>(b.cid,b.ctg_off,b.contigs,b.reads,b.quals,b.read_off,b.read_count,b.depth,b.table,b.prefix,b.visited,21,MO,b.terms,0,MW,0,70,16,33,b.longest,b.temp,b.lens,NC);ck(cudaDeviceSynchronize());return std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count();}
static std::vector<unsigned>capture(Buffers&b){capture_hash<<<(NC*HT+255)/256,256>>>(b.table,b.hashes,NC*HT);ck(cudaDeviceSynchronize());std::unique_ptr<unsigned char[]>raw(new unsigned char[NC*HT*sizeof(loc_ht)]),visraw(new unsigned char[NC*MW*sizeof(loc_ht_bool)]);ck(cudaMemcpy(raw.get(),b.table,NC*HT*sizeof(loc_ht),cudaMemcpyDeviceToHost));ck(cudaMemcpy(visraw.get(),b.visited,NC*MW*sizeof(loc_ht_bool),cudaMemcpyDeviceToHost));auto table=reinterpret_cast<loc_ht*>(raw.get());auto visited=reinterpret_cast<loc_ht_bool*>(visraw.get());std::vector<unsigned>hashes(NC*HT),lens(NC);std::vector<unsigned char>longest(NC*MW),temp(NC*(MW+MO));ck(cudaMemcpy(hashes.data(),b.hashes,hashes.size()*4,cudaMemcpyDeviceToHost));ck(cudaMemcpy(lens.data(),b.lens,lens.size()*4,cudaMemcpyDeviceToHost));ck(cudaMemcpy(longest.data(),b.longest,longest.size(),cudaMemcpyDeviceToHost));ck(cudaMemcpy(temp.data(),b.temp,temp.size(),cudaMemcpyDeviceToHost));std::vector<unsigned>out;for(int group=0;group<NC;++group){if(lens[group]>MW){fprintf(stderr,"Invalidwalklength\n");exit(3);}out.push_back(lens[group]);for(int i=0;i<MW;++i)out.push_back(longest[group*MW+i]);for(int i=0;i<MW+MO;++i)out.push_back(temp[group*(MW+MO)+i]);std::vector<std::vector<unsigned>>records,seen;for(int slot=0;slot<HT;++slot){int idx=group*HT+slot;auto&e=table[idx];if(e.key.length==int(EMPTY))continue;if(e.key.length!=21){fprintf(stderr,"InvalidHTkeylength %d\n",e.key.length);exit(3);}std::vector<unsigned char>key(21);ck(cudaMemcpy(key.data(),e.key.start_ptr,21,cudaMemcpyDeviceToHost));std::vector<unsigned>r(key.begin(),key.end());auto&v=e.val;r.insert(r.end(),{v.low_q_exts.count_A,v.low_q_exts.count_C,v.low_q_exts.count_G,v.low_q_exts.count_T,v.hi_q_exts.count_A,v.hi_q_exts.count_C,v.hi_q_exts.count_G,v.hi_q_exts.count_T,unsigned((unsigned char)v.ext),unsigned(v.count),hashes[idx]});records.push_back(r);}std::sort(records.begin(),records.end());if(records.size()>CAP)exit(3);out.push_back(records.size());for(auto&r:records)out.insert(out.end(),r.begin(),r.end());out.insert(out.end(),(CAP-records.size())*32,0);for(int slot=0;slot<MW;++slot){auto&e=visited[group*MW+slot];if(e.key.length==int(EMPTY))continue;if(e.key.length!=21)exit(3);std::vector<unsigned char>key(21);ck(cudaMemcpy(key.data(),e.key.start_ptr,21,cudaMemcpyDeviceToHost));std::vector<unsigned>r(key.begin(),key.end());r.push_back(e.val?1:0);seen.push_back(r);}std::sort(seen.begin(),seen.end());out.push_back(seen.size());for(auto&r:seen)out.insert(out.end(),r.begin(),r.end());out.insert(out.end(),(MW-seen.size())*22,0);}return out;}
int main(){Buffers b{};b.cid=device_copy(std::vector<unsigned>{0,1,2,3,4});b.ctg_off=device_copy(FIX_ctg_offsets);b.read_off=device_copy(FIX_read_offsets);b.read_count=device_copy(FIX_read_counts);b.prefix=device_copy(FIX_prefix_ht);b.contigs=reinterpret_cast<char*>(device_copy(FIX_contigs));b.reads=reinterpret_cast<char*>(device_copy(FIX_reads));b.quals=reinterpret_cast<char*>(device_copy(FIX_quals));b.depth=device_copy(std::vector<double>(5,10.));ck(cudaMalloc(&b.terms,12));ck(cudaMalloc(&b.lens,NC*4));ck(cudaMalloc(&b.hashes,NC*HT*4));ck(cudaMalloc(&b.longest,NC*MW));ck(cudaMalloc(&b.temp,NC*(MW+MO)));ck(cudaMalloc(&b.table,NC*HT*sizeof(loc_ht)));ck(cudaMalloc(&b.visited,NC*MW*sizeof(loc_ht_bool)));std::vector<unsigned>expected(EXPECTED_COUNT,0);for(auto p:EXPECTED_NONZERO)expected[p.first]=p.second;run(b);capture(b);for(int trial=1;trial<=5;++trial){double elapsed=run(b);auto got=capture(b);bool ok=got==expected;if(!ok){int mismatches=0;for(size_t i=0;i<got.size();++i)if(got[i]!=expected[i]){if(mismatches++<30)fprintf(stderr,"Mismatch slot%zu actual%u expected%u\n",i,got[i],expected[i]);}fprintf(stderr,"total mismatches%d\n",mismatches);}std::vector<unsigned>out=FIX_input_prefix;out.insert(out.end(),got.begin(),got.end());std::string path="trial_"+std::to_string(trial)+".bin";FILE*f=fopen(path.c_str(),"wb");fwrite(out.data(),4,out.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.17g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":0,\"timing_region\":\"integrated_right_kmer_count_quality_walk_kernel_only\",\"jit_excluded\":true,\"internal_repeats\":1,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"uint32\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,elapsed,ok?"true":"false",TOTAL_COUNT,path.c_str(),TOTAL_COUNT);if(!ok)return 3;}for(void*p:{(void*)b.cid,(void*)b.ctg_off,(void*)b.read_off,(void*)b.read_count,(void*)b.prefix,(void*)b.contigs,(void*)b.reads,(void*)b.quals,(void*)b.depth,(void*)b.terms,(void*)b.lens,(void*)b.hashes,(void*)b.longest,(void*)b.temp,(void*)b.table,(void*)b.visited})cudaFree(p);return 0;}
